CREATE TABLE worker_cache_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT INTO worker_cache_revision VALUES (1,1);
CREATE TRIGGER cache_item_insert AFTER INSERT ON hub_item BEGIN UPDATE worker_cache_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER cache_item_delete AFTER DELETE ON hub_item BEGIN UPDATE worker_cache_revision SET revision=revision+1 WHERE id=1; END;
